        row[7] = self.def.0 as f64;
        self.owner.put(&mut row[8..8 + 3], heap);
        row[11..11 + 3].copy_from_slice(&self.position);
        row[14..14 + 3].copy_from_slice(&self.previous);
        row[17..17 + 3].copy_from_slice(&self.launch_position);
        row[20..20 + 3].copy_from_slice(&self.velocity);
        row[23] = self.life;
        match &self.impact { Some(v) => { row[24] = 0.0; v.put(&mut row[24 + 1..], heap); } None => { row[24] = 1.0; row[24 + 1..24 + 16].fill(0.0); } }
        row[40] = if self.dead { 1.0 } else { 0.0 };
        row[41] = self.gravity;
        row[42] = self.ramp;
        row[43..43 + 3].copy_from_slice(&self.desired);
        match &self.target_id { Some(v) => { row[46] = 0.0; row[46 + 1] = (*v); } None => { row[46] = 2.0; row[46 + 1..46 + 2].fill(0.0); } }
        match &self.target_generation { Some(v) => { row[48] = 0.0; row[48 + 1] = (*v); } None => { row[48] = 2.0; row[48 + 1..48 + 2].fill(0.0); } }
        row[50..50 + 2].copy_from_slice(&self.phase);
        row[52..52 + 4].copy_from_slice(&self.quaternion);
        match &self.struck { Some(v) => { row[56] = 0.0; row[56 + 1] = heap.len() as f64; row[56 + 1 + 1] = v.items.len() as f64; for r in v.items.iter() { heap.push(r.slot as f64); heap.push(r.gen as f64); } } None => { row[56] = 2.0; row[56 + 1..56 + 3].fill(0.0); } }
        match &self.gone { Some(v) => { row[59] = 0.0; row[59 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[59] = 2.0; row[59 + 1..59 + 2].fill(0.0); } }
        match &self.flight_missile { Some(v) => { row[61] = 0.0; row[61 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[61] = 2.0; row[61 + 1..61 + 2].fill(0.0); } }
        match &self.flight_class { Some(v) => { row[63] = 0.0; row[63 + 1] = (*v).0 as f64; } None => { row[63] = 2.0; row[63 + 1..63 + 2].fill(0.0); } }
