        self.previous = [row[14], row[14 + 1], row[14 + 2]];
        self.launch_position = [row[17], row[17 + 1], row[17 + 2]];
        self.velocity = [row[20], row[20 + 1], row[20 + 2]];
        self.life = row[23];
        self.impact = if row[24] == 0.0 { Some(Impact::take(&row[24 + 1..], heap)) } else { None };
        self.dead = row[40] != 0.0;
        self.gravity = row[41];
        self.ramp = row[42];
        self.desired = [row[43], row[43 + 1], row[43 + 2]];
